    @EventHandler( payloadType=CreateRateCardEvent.class )
    public void handle( CreateRateCardEvent event) {
	    LOGGER.info("handling CreateRateCardEvent - " + event );
	    RateCard entity = new RateCard();
            entity.setRateCardId( event.getRateCardId() );
            entity.setName( event.getName() );
            entity.setEffectiveDate( event.getEffectiveDate() );
            entity.setCurrency( event.getCurrency() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllRateCard( entity );
    }

    /*
     * @param	event UpdateRateCardEvent
     */
    @EventHandler( payloadType=UpdateRateCardEvent.class )
    public void handle( UpdateRateCardEvent event) {
    	LOGGER.info("handling UpdateRateCardEvent - " + event );
    	
	    RateCard entity = new RateCard();
            entity.setRateCardId( event.getRateCardId() );
            entity.setName( event.getName() );
            entity.setEffectiveDate( event.getEffectiveDate() );
            entity.setCurrency( event.getCurrency() );
            entity.setPublisher( event.getPublisher() );
            entity.setRates( event.getRates() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindRateCard( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllRateCard( entity );        
    }
    
