/**
 * emit to subscription queries of type FindRateCard,
 * but only if the id matches
 *
 * @param		entity	RateCard
 */
	protected void emitFindRateCard( RateCard entity ) {
		LOGGER.info("handling emitFindRateCard" );
		
	    queryUpdateEmitter.emit(FindRateCardQuery.class,
	                            query -> query.getFilter().getRateCardId().equals(entity.getRateCardId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllRateCard
	 * 
	 * @param		entity	RateCard
	 */
	protected void emitFindAllRateCard( RateCard entity ) {
		LOGGER.info("handling emitFindAllRateCard" );
		
	    queryUpdateEmitter.emit(FindAllRateCardQuery.class,
	                            query -> true,
	                            entity);
	}

